window.S17Page={"sceneId":"t2","caseId":"s17x-t2-corrosion-growth","name":"管道腐蚀智能评估","title":"管道腐蚀评估：先找对缺陷，再谈增长","summary":"两次智能清管记录中的同一处金属损失，位置可能并不完全重合。先把两次记录配准、匹配，再用壁厚损失的变化筛选优先开挖位置。","directory":"expansion-cases","caseVersion":"1.2.1","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){"use strict";function mean(a){return a.reduce((s,x)=>s+x,0)/a.length}function mae(a,b){return mean(a.map((v,i)=>Math.abs(v-b[i])))}function reg(x,y){let xm=mean(x),ym=mean(y);let b=x.reduce((s,v,i)=>s+(v-xm)*(y[i]-ym),0)/(x.reduce((s,v)=>s+(v-xm)**2,0)||1);return {a:ym-b*xm,b}}function median(a){a=a.slice().sort((x,y)=>x-y);return a[Math.floor(a.length/2)]}function rng(seed){return ()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296}}function run(p){let R=rng(224),n=24,t=p.years;let old=Array.from({length:n},(_,i)=>({x:100+i*8+R()*2,angle:(i*71)%360,len:40+R()*70,depth:1+R()*3}));let truthRates=old.map(()=>.03+R()*.35),oldObserved=old.map(r=>({...r,depth:r.depth+(R()-.5)*p.noise*.5}));let current=old.map((r,i)=>({x:r.x+p.shift+(R()-.5)*.3,angle:r.angle+(R()-.5)*3,len:r.len+(R()-.5)*5,depth:r.depth+truthRates[i]*t+(R()-.5)*p.noise*.5}));let shuffled=current.map((r,i)=>({observation:r,referenceIndex:i}));for(let j=shuffled.length-1;j>0;j--){let k=Math.floor(R()*(j+1));[shuffled[j],shuffled[k]]=[shuffled[k],shuffled[j]];}let referenceIndex=shuffled.map(r=>r.referenceIndex);current=shuffled.map(r=>r.observation);let anchors=[0,100,200,300,400].map(x=>({old:x,now:x+p.shift+(R()-.5)*.12}));let offset=median(anchors.map(x=>x.now-x.old));function match(shift,smart){let used=new Set();return old.map(o=>{let cs=current.map((r,j)=>({j,c:Math.abs(r.x-shift-o.x)+(smart?Math.min(Math.abs(r.angle-o.angle),360-Math.abs(r.angle-o.angle))*.12+Math.abs(r.len-o.len)*.03:0)})).filter(z=>!smart||!used.has(z.j)).sort((a,b)=>a.c-b.c);used.add(cs[0].j);return cs[0].j})}let pred=match(offset,true),base=match(0,false);let rates=oldObserved.map((o,i)=>(current[pred[i]].depth-o.depth)/t),br=oldObserved.map((o,i)=>(current[base[i]].depth-o.depth)/t);let acc=a=>100*mean(a.map((j,i)=>+(referenceIndex[j]===i)));let rows=oldObserved.map((o,i)=>[i+1,o.x.toFixed(2),current[pred[i]].x.toFixed(2),(current[pred[i]].x-offset).toFixed(2),o.depth.toFixed(3),current[pred[i]].depth.toFixed(3),rates[i].toFixed(3),rates[i]>0?Math.max(0,(6-current[pred[i]].depth)/rates[i]).toFixed(1):'不外推']);return {summary:'焊缝配准偏移 '+offset.toFixed(2)+' m；按增长率由大到小复核对应缺陷。',metrics:[['配准匹配正确率',acc(pred).toFixed(1)+'%'],['基线正确率',acc(base).toFixed(1)+'%'],['增长率 MAE',mae(rates,truthRates).toFixed(3)+' mm/年'],['基线 MAE',mae(br,truthRates).toFixed(3)+' mm/年']],charts:[{title:'配准前后的坐标残差：相对首次里程',xlabel:'首次缺陷记录序号',indexStart:1,ylabel:'二次−首次里程 m',series:[{name:'首次坐标零差',y:old.map(()=>0)},{name:'二次原始里程差',y:pred.map((j,i)=>current[j].x-old[i].x)},{name:'二次配准后里程差',y:pred.map((j,i)=>current[j].x-offset-old[i].x)}]},{indexStart:1,title:'各缺陷的增长率：配准路线与未配准基线',xlabel:'缺陷记录序号',ylabel:'mm/年',series:[{name:'配准匹配',y:rates},{name:'原始里程基线',y:br},{name:'独立评价参考',y:truthRates}]}],headers:['首次缺陷','首次里程 m','二次原始里程 m','二次校正里程 m','首次损失 mm','二次损失 mm','增长 mm/年','距6mm触发线 年'],rows:rows.sort((a,b)=>Number(b[6])-Number(a[6])),denominator:n,offset,anchors,observations:{first:oldObserved,second:current},evaluationTruth:{matching:referenceIndex,growthRates:truthRates},referenceUsedOnlyInEvaluation:true}};g.TransportEngine={run:run};})(globalThis);

